// learn-nav.js -- the Learn series' icons in the book's sidebar: each lesson's
// icon beside its title, and each branch's beside the branch name, from
// learn-icons.js (generated by gen_learn_tree.mjs from playground/learn.js).
(function () {
  'use strict';

  const data = window.wsLearnIcons;
  if (!data) return;
  const root = typeof path_to_root === 'string' ? path_to_root : '';
  const bookRoot = new URL(root, document.baseURI).pathname;
  const SVG = 'http://www.w3.org/2000/svg';

  function iconEl(name) {
    const shape = data.icons[name];
    if (!shape) return null;
    const svg = document.createElementNS(SVG, 'svg');
    svg.setAttribute('viewBox', '0 0 ' + shape[0] + ' ' + shape[1]);
    svg.setAttribute('class', 'learn-nav-icon');
    svg.setAttribute('aria-hidden', 'true');
    const path = document.createElementNS(SVG, 'path');
    path.setAttribute('d', shape[2]);
    path.setAttribute('fill', 'currentColor');
    svg.appendChild(path);
    return svg;
  }

  /** `learn/random/dice` for a link to `.../learn/random/dice.html`. */
  function pageOf(href) {
    const path = decodeURIComponent(new URL(href, document.baseURI).pathname);
    if (!path.startsWith(bookRoot)) return null;
    return path.slice(bookRoot.length).replace(/\.html$/, '');
  }

  function decorate(sidebar) {
    for (const wrap of sidebar.querySelectorAll('.chapter-link-wrapper')) {
      if (wrap.querySelector('.learn-nav-icon')) continue;
      const first = wrap.firstElementChild;
      if (!first) continue;
      let name = null;
      const href = first.getAttribute('href');
      // A link with an anchor is one of the open page's headings, not a page.
      if (first.tagName === 'A' && href && !href.includes('#')) {
        const page = pageOf(href);
        name = page && data.pages[page];
      } else if (first.tagName === 'SPAN') {
        name = data.branches[first.textContent.trim()];
      }
      const icon = name && iconEl(name);
      if (icon) first.prepend(icon);
    }
  }

  function start() {
    const sidebar = document.querySelector('mdbook-sidebar-scrollbox, .sidebar-scrollbox, #sidebar');
    if (!sidebar) return;
    decorate(sidebar);
    // The sidebar may be filled in after this runs; decorate what arrives.
    new MutationObserver(() => decorate(sidebar)).observe(sidebar, { childList: true, subtree: true });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
